# Bioinf.xs needs C99: // comments, declarations after statements and in for(),
# and `restrict` where the compiler has a spelling for it.  The flag that asks
# for C99 is per-vendor, and it cannot be guessed from $Config{cc}: that is
# plain "cc" for Oracle Studio on Solaris and for aCC on HP-UX, both of which
# would fail the build on an illegal option if handed -std=gnu99.  So each
# candidate is trial-compiled and the first one that actually works wins:
# -std=gnu99/-std=c99 for gcc and clang (all BSDs included), -xc99=all for
# Studio, -qlanglvl=extc99 for AIX xlc, -AC99 for HP-UX, and finally '' for a
# compiler whose default mode is already C99.  MSVC is skipped outright -- it
# needs no flag for any of the above and merely warns on switches it does not
# know, which would make the probe pick a no-op.  This is the probe from
# ~/Scripts/stats/dist.ini. Its x87 probe is left out: Bioinf.xs splits no
# product into whole and fractional parts, where excess precision changes an
# answer and not only its last digit.
my $std = '';
unless ($Config{cc} =~ /(?:^|[\/\\])cl(?:\.exe)?$/i) {
my $c99 = "#include <stdint.h>\n"
. "int main(void) { uint64_t u = 0; // C99 comment\n"
. "for (int i = 0; i < 3; i++) { u += (uint64_t)i; }\n"
. "return (int)(u - 3); }\n";
my $dir = File::Temp::tempdir(CLEANUP => 1);
my $src = File::Spec->catfile($dir, 'c99probe.c');
my $obj = File::Spec->catfile($dir, 'c99probe.o');
if (open my $probe_fh, '>', $src) {
print {$probe_fh} $c99;
close $probe_fh;
my $quiet = File::Spec->devnull;
for my $flag ('-std=gnu99', '-std=c99', '-xc99=all', '-qlanglvl=extc99', '-AC99', '') {
# quoted, since a temporary directory can have a space in it (a Windows
# user name), and every flag would then fail and none be chosen
next if system("$Config{cc} $flag -c \"$src\" -o \"$obj\" > $quiet 2> $quiet") != 0;
$std = $flag eq '' ? '' : " $flag";
last;
}
}
}
# On a long-double perl, admixture's fit in Bioinf.xs wants logl() and sqrtl(),
# so that an NV is not computed at a double's precision. They are C99, but some
# libms (the thinner BSD ones especially) lack them, so they are link-tested,
# and without them Bioinf.xs uses log() and sqrt(). __float128 needs no probe:
# quadmath.h and -lquadmath come with the quadmath perl itself. This is the
# probe of ~/Scripts/stats, cut down to the two functions used.
my $define = '';
if ($Config{nvtype} eq 'long double') {
my $dir = File::Temp::tempdir(CLEANUP => 1);
my $src = File::Spec->catfile($dir, 'ldmath.c');
my $bin = File::Spec->catfile($dir, 'ldmath');
if (open my $ld_fh, '>', $src) {
print {$ld_fh} "#include <math.h>\nint main(void) { volatile long double x = 2.0L; volatile long double r = logl(x) + sqrtl(x); return (int)r * 0; }\n";
close $ld_fh;
my $quiet = File::Spec->devnull;
$define = '-DBIOINF_HAVE_LONG_DOUBLE_MATH'
if system("$Config{cc}$std -o \"$bin\" \"$src\" -lm > $quiet 2> $quiet") == 0;
}
}

